const f = require('../functions');

exports.protocol = 'GT06+';
exports.model_name = 'GT06+ Enhanced';
exports.compatible_hardware = ['GT06N', 'GT06', 'GT06E', 'GT06F', 'GT06H', 'TK103', 'TK303', 'UM552'];

var adapter = function (device) {
  if (!(this instanceof adapter)) {
    return new adapter(device);
  }

  this.format = {'start': '(', 'end': ')', 'separator': ''};
  this.device = device;
  this.__count = 1;

  /*******************************************
   SIMPLIFIED BUT WORKING PARSER
   *******************************************/
  this.parse_data = function (data) {
    try {
      var hexData = this.bufferToHexString(data);
      console.log('Raw hex data received:', hexData);
      
      if (hexData.length < 10) {
        return { cmd: 'noop', action: 'noop', device_id: '' };
      }

      var parts = {
        'raw': hexData,
        'raw_buffer': data,
        'start': hexData.substr(0, 4)
      };

      if (parts['start'] !== '7878' && parts['start'] !== '7979') {
        return { cmd: 'noop', action: 'noop', device_id: '' };
      }

      // Parse basic structure
      parts['length'] = parseInt(hexData.substr(4, 2), 16);
      parts['protocol_id'] = hexData.substr(6, 2).toLowerCase();
      console.log('Protocol ID:', parts['protocol_id']);
      
      // Extract data section
      const dataStart = 8;
      parts['data'] = hexData.substring(dataStart, dataStart + (parts['length'] - 1) * 2);
      
      // Get device ID - CRITICAL FIX
      let deviceId = null;
      
      // For login packets (protocol 01)
      if (parts['protocol_id'] === '01') {
        deviceId = this.extractIMEISimple(hexData);
        parts['device_id'] = deviceId;
        console.log(`Login packet, extracted IMEI: ${deviceId}`);
      } else {
        // For other packets, get from device object
        deviceId = this.device.getUID ? this.device.getUID() : null;
        parts['device_id'] = deviceId;
      }
      
      // Create SIMPLE analysis - always attach it
      parts['analysis'] = this.createSimpleAnalysis(hexData, parts['protocol_id'], deviceId);
      
      console.log(`Analysis attached: ${parts['analysis'].brands.join(', ')} - ${parts['analysis'].packetType}`);
      
      // Map protocol to action
      this.map_gt06_protocol(parts);

      console.log(`Parsed: Protocol=${parts['protocol_id']}, Action=${parts.action}, DeviceID=${deviceId || 'none'}`);
      return parts;
    } catch (error) {
      console.error('Error parsing data:', error);
      return { cmd: 'noop', action: 'noop', device_id: '' };
    }
  };

  // SIMPLE IMEI extraction
  this.extractIMEISimple = function(hexData) {
    try {
      // GT06 login: 7878 0D 01 [IMEI 8 bytes] [Serial 2 bytes] [CRC 2 bytes] 0D0A
      if (hexData.length < 24) return null;
      
      const imeiHex = hexData.substring(8, 24); // 8 bytes = 16 hex chars
      console.log(`IMEI Hex: ${imeiHex}`);
      
      // Simple conversion: each hex char is a BCD digit
      let imei = '';
      for (let i = 0; i < imeiHex.length; i++) {
        const hexChar = imeiHex.charAt(i);
        const decimal = parseInt(hexChar, 16);
        imei += decimal.toString();
      }
      
      // IMEI should be 15 digits
      if (imei.length > 15) {
        imei = imei.substring(0, 15);
      }
      
      return imei;
    } catch (error) {
      console.error('Error extracting IMEI:', error);
      return null;
    }
  };

  // SIMPLE analysis creation - ALWAYS returns analysis
  this.createSimpleAnalysis = function(hexData, protocolId, deviceId) {
    const analysis = {
      timestamp: new Date().toISOString(),
      deviceId: deviceId,
      isGT06: true,
      protocolNumber: protocolId,
      packetType: 'Unknown',
      brands: [],
      protocols: ['GT06']
    };

    try {
      // Set packet type based on protocol
      const protocolMap = {
        '01': 'Login',
        '12': 'Location',
        '13': 'Heartbeat',
        '16': 'Alarm',
        '1a': 'Address Query',
        '22': 'GPS + Address',
        '26': 'Alarm + Address'
      };
      
      analysis.packetType = protocolMap[protocolId] || 'Unknown';
      
      // Brand detection
      if (deviceId) {
        // Teltonika
        if (deviceId.startsWith('086872') || deviceId.startsWith('86872')) {
          analysis.brands.push('Teltonika');
        }
        // Queclink
        else if (deviceId.startsWith('035865') || deviceId.startsWith('35865')) {
          analysis.brands.push('Queclink');
        }
        // Suntech
        else if (deviceId.startsWith('086494') || deviceId.startsWith('86494')) {
          analysis.brands.push('Suntech');
        }
        // Concox
        else if (deviceId.startsWith('86108')) {
          analysis.brands.push('Concox');
        }
        // Meitrack
        else if (deviceId.startsWith('86219')) {
          analysis.brands.push('Meitrack');
        }
        
        // Default for GT06 devices
        if (analysis.brands.length === 0) {
          analysis.brands.push('GT06 Family');
        }
      }
      
    } catch (error) {
      console.error('Error in createSimpleAnalysis:', error);
    }

    return analysis;
  };

  this.map_gt06_protocol = function(parts) {
    const protocolMap = {
      '01': { cmd: 'login_request', action: 'login_request' },
      '10': { cmd: 'ping', action: 'ping' },
      '11': { cmd: 'ping', action: 'ping' },
      '12': { cmd: 'ping', action: 'ping' },
      '13': { cmd: 'heartbeat', action: 'heartbeat' },
      '16': { cmd: 'alarm', action: 'alarm' },
      '17': { cmd: 'lbs_location', action: 'lbs_location' },
      '18': { cmd: 'status', action: 'status' },
      '19': { cmd: 'status', action: 'status' },
      '1a': { cmd: 'alarm', action: 'alarm' },
      '1b': { cmd: 'alarm', action: 'alarm' },
      '1c': { cmd: 'alarm', action: 'alarm' },
      '22': { cmd: 'ping', action: 'ping' },
      '26': { cmd: 'alarm', action: 'alarm' },
      '27': { cmd: 'alarm', action: 'alarm' },
      '28': { cmd: 'ping', action: 'ping' },
      '2a': { cmd: 'alarm', action: 'alarm' },
      '2b': { cmd: 'alarm', action: 'alarm' },
      '2c': { cmd: 'alarm', action: 'alarm' }
    };

    const mapping = protocolMap[parts['protocol_id']] || { cmd: 'noop', action: 'noop' };
    parts.cmd = mapping.cmd;
    parts.action = mapping.action;
  };

  this.bufferToHexString = function (buffer) {
    var str = '';
    for (var i = 0; i < buffer.length; i++) {
      var hex = buffer[i].toString(16);
      str += hex.length === 1 ? '0' + hex : hex;
    }
    return str;
  };

  this.authorize = function () {
    var response = '787805010001D9DC0D0A';
    console.log('Sending login response:', response);
    this.device.send(Buffer.from(response, 'hex'));
  };
  
  this.receive_heartbeat = function (msg_parts) {
    var response = '787805130001D9DC0D0A';
    console.log('Sending heartbeat response:', response);
    this.device.send(Buffer.from(response, 'hex'));
  };

  // GPS parsing methods (keep your existing)
  this.get_ping_data = function (msg_parts) {
    try {
      var str = msg_parts.data_body || msg_parts.data;
      console.log('Parsing location data, length:', str.length);
      
      if (str.length >= 38) {
        return this.parse_standard_gps_data(str, msg_parts);
      } else if (str.length >= 20) {
        return this.parse_compact_gps_data(str, msg_parts);
      } else {
        console.error('GPS data too short:', str.length);
        return false;
      }
    } catch (error) {
      console.error('Error parsing ping data:', error);
      return false;
    }
  };

  this.parse_standard_gps_data = function (str, msg_parts) {
    // Parse date: 6 bytes (12 hex chars) - YYMMDDHHMMSS
    const dateHex = str.substr(0, 12);
    const year = parseInt(dateHex.substr(0, 2), 16) + 2000;
    const month = parseInt(dateHex.substr(2, 2), 16);
    const day = parseInt(dateHex.substr(4, 2), 16);
    const hour = parseInt(dateHex.substr(6, 2), 16);
    const minute = parseInt(dateHex.substr(8, 2), 16);
    const second = parseInt(dateHex.substr(10, 2), 16);
    const date = new Date(year, month - 1, day, hour, minute, second);
    
    // Parse satellites (1 byte)
    const satellites = parseInt(str.substr(12, 2), 16);
    
    // Parse latitude (4 bytes = 8 hex chars)
    const latHex = str.substr(14, 8);
    let latitude = 0;
    if (latHex !== '00000000') {
      latitude = parseInt(latHex, 16) / 1800000;
    }
    
    // Parse longitude (4 bytes = 8 hex chars)
    const lngHex = str.substr(22, 8);
    let longitude = 0;
    if (lngHex !== '00000000') {
      longitude = parseInt(lngHex, 16) / 1800000;
    }
    
    // Parse speed (1 byte)
    const speed = parseInt(str.substr(30, 2), 16);
    
    // Parse course/heading (2 bytes = 4 hex chars)
    const courseHex = str.substr(32, 4);
    let course = parseInt(courseHex, 16);
    
    // Fix course
    if (course > 360) {
      course = course & 0xFF;
      course = (course * 360) / 255;
    }
    course = Math.round(course);
    
    const data = {
      device_id: msg_parts.device_id || '',
      date: date.toISOString(),
      timestampDate: date,
      latitude: latitude,
      longitude: longitude,
      speed: speed,
      orientation: course,
      satellites: satellites,
      raw_data: str
    };
    
    console.log('Parsed location:', {
      device: data.device_id,
      lat: data.latitude,
      lng: data.longitude,
      speed: data.speed,
      course: data.orientation,
      time: data.date
    });
    
    return data;
  };

  this.parse_compact_gps_data = function (str, msg_parts) {
    const date = new Date();
    
    let latitude = 0;
    let longitude = 0;
    let speed = 0;
    
    if (str.length >= 20) {
      try {
        const latPart = str.substr(0, 8);
        const lngPart = str.substr(8, 8);
        
        if (latPart !== '00000000' && lngPart !== '00000000') {
          latitude = parseInt(latPart, 16) / 1800000;
          longitude = parseInt(lngPart, 16) / 1800000;
        }
        
        if (str.length >= 22) {
          speed = parseInt(str.substr(16, 2), 16);
        }
      } catch (e) {
        console.error('Error parsing compact GPS:', e);
      }
    }
    
    return {
      device_id: msg_parts.device_id || '',
      date: date.toISOString(),
      timestampDate: date,
      latitude: latitude,
      longitude: longitude,
      speed: speed,
      orientation: 0,
      satellites: 0,
      raw_data: str
    };
  };

  // Alarm parsing (simplified)
  this.receive_alarm = function (msg_parts) {
    try {
      const deviceId = msg_parts.device_id || this.device.getUID ? this.device.getUID() : null;
      
      // Create simple alarm data
      const alarmData = {
        code: '01',
        msg: 'Alarm',
        device_id: deviceId,
        date: new Date().toISOString(),
        timestampDate: new Date(),
        alarm_type: 'Unknown Alarm',
        alarm_code: '01',
        raw_data: msg_parts.raw,
        protocol_id: msg_parts.protocol_id
      };
      
      console.log(`Alarm from ${deviceId}`);
      return alarmData;
    } catch (error) {
      console.error('Error parsing alarm:', error);
      return false;
    }
  };
};

exports.adapter = adapter;